import requests
from flask import Flask, request, redirect, session
import uuid

app = Flask(__name__)
app.secret_key = 'your_secret_key'

AUTH0_DOMAIN = 'your_auth0_domain'
AUTH0_CLIENT_ID = 'your_auth0_client_id'
AUTH0_CLIENT_SECRET = 'your_auth0_client_secret'
AUTH0_CALLBACK_URL = 'http://localhost:5000/callback'

@app.route('/')
def login():
    code_verifier = str(uuid.uuid4())
    session['code_verifier'] = code_verifier
    code_challenge = create_code_challenge(code_verifier)
    authorization_url = f'https://{AUTH0_DOMAIN}/authorize?response_type=code&client_id={AUTH0_CLIENT_ID}&redirect_uri={AUTH0_CALLBACK_URL}&scope=openid%20profile&code_challenge={code_challenge}&code_challenge_method=S256'
    return redirect(authorization_url)

@app.route('/callback')
def callback():
    authorization_code = request.args.get('code')
    token_url = f'https://{AUTH0_DOMAIN}/oauth/token'
    token_payload = {
        'grant_type': 'authorization_code',
        'client_id': AUTH0_CLIENT_ID,
        'client_secret': AUTH0_CLIENT_SECRET,
        'code': authorization_code,
       'redirect_uri': AUTH0_CALLBACK_URL,
        'code_verifier': session['code_verifier']
    }
    token_response = requests.post(token_url, data=token_payload)
    tokens = token_response.json()
    session['access_token'] = tokens['access_token']
    return redirect('/profile')

@app.route('/profile')
def profile():
    if 'access_token' not in session:
        return redirect('/')
    userinfo_url = f'https://{AUTH0_DOMAIN}/userinfo'
    headers = {'Authorization': f'Bearer {session["access_token"]}'}
    userinfo_response = requests.get(userinfo_url, headers=headers)
    user_profile = userinfo_response.json()
    return f'User Profile: {user_profile}'

def create_code_challenge(code_verifier):
    import hashlib
    import base64
    digest = hashlib.sha256(code_verifier.encode()).digest()
    code_challenge = base64.urlsafe_b64encode(digest).decode().rstrip('=')
    return code_challenge

if __name__ == '__main__':
    app.run(port=5000)
